{"path":"assets/css/styles.css","content":":root{
  --bg:#fbf7f2;
  --card:#fff7f0;
  --accent:#8b5e34;
  --muted:#6b5a50;
  --accent-2:#c99156;
  --radius:12px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto, "Helvetica Neue", Arial;line-height:1.45;color:var(--muted);background:var(--bg)}
.wrap{max-width:var(--max-width);margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(180deg, rgba(139,94,52,0.06), transparent);border-bottom:1px solid rgba(107,90,80,0.06)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none}
.nav a{margin-left:1rem;color:var(--muted);text-decoration:none;font-size:0.95rem}
.nav a.cta{background:var(--accent);color:#fff;padding:0.45rem 0.8rem;border-radius:8px}
.hero{padding:5rem 0;background-size:320px;background-repeat:repeat}
.hero-inner{max-width:720px;background:rgba(255,255,255,0.8);padding:2rem;border-radius:12px}
.title{margin:0 0 0.5rem;color:var(--accent)}
.lede{margin:0 0 1rem;color:#5b4a41}
.btn{display:inline-block;padding:0.6rem 1rem;border-radius:8px;text-decoration:none;border:1px solid rgba(0,0,0,0.04);background:transparent;color:var(--accent);cursor:pointer}
.btn.primary{background:var(--accent);color:#fff;border:none}
.btn.ghost{background:transparent;border:1px solid rgba(139,94,52,0.12)}
.social-proof h2,.benefits h2,.process h2,.faq h2,.final-cta h2{color:var(--accent)}
.proof-list{list-style:none;padding:0;margin:0;display:flex;gap:1rem}
.proof-list li{background:var(--card);padding:0.8rem;border-radius:10px;flex:1}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin-top:1rem}
.card{background:linear-gradient(180deg, #fff, var(--card));padding:1rem;border-radius:10px}
.process-list{padding-left:1.2rem}
.session-planner{margin-top:1.5rem;background:#fff;padding:1rem;border-radius:10px;border:1px solid rgba(107,90,80,0.06)}
.session-planner form{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:0.6rem;align-items:start}
.session-planner label{display:block;font-size:0.9rem}
.session-planner input[type="text"],.session-planner select,.session-planner input[type="number"]{width:100%;padding:0.5rem;border-radius:8px;border:1px solid rgba(0,0,0,0.06)}
.checkboxes{grid-column:1/-1;display:flex;gap:0.6rem;flex-wrap:wrap}
.planner-actions{grid-column:1/-1;display:flex;gap:0.6rem;align-items:center}
#plan-output{white-space:pre-wrap;margin-top:0.8rem;background:#fbf6f3;padding:0.8rem;border-radius:8px;border:1px solid rgba(0,0,0,0.03);min-height:4rem}
.faq details{background:var(--card);padding:0.8rem;border-radius:8px;margin-bottom:0.6rem}
.final-cta{padding:2rem 0;text-align:center}
.cta-row{display:flex;gap:0.8rem;justify-content:center}
.site-footer{border-top:1px solid rgba(107,90,80,0.04);padding:1rem 0;margin-top:2rem}
@media (max-width:700px){
  .nav{display:none}
  .wrap{padding:1rem}
  .hero{padding:3rem 0}
}

/* reveal animation */
.reveal{opacity:0;transform:translateY(12px);transition:opacity 420ms ease, transform 420ms cubic-bezier(.2,.9,.28,1)}
.reveal.active{opacity:1;transform:none}

@media (prefers-reduced-motion: reduce){
  .reveal{transition:none;opacity:1;transform:none}
}

/* small utilities */
.small{font-size:0.9rem;color:#5b4a41}
pre{font-family:Menlo,Monaco,monospace;font-size:0.9rem}
"} 
{"path":"assets/js/main.js","content":"(function(){
  "use strict";

  // Scroll-triggered reveal with prefers-reduced-motion support
  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function setupReveal(){
    var nodes = Array.prototype.slice.call(document.querySelectorAll('[data-reveal]'));
    if(prefersReduced || !('IntersectionObserver' in window)){
      nodes.forEach(function(n){n.classList.add('active');});
      return;
    }
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){
          e.target.classList.add('active');
          io.unobserve(e.target);
        }
      });
    },{threshold:0.12});

    nodes.forEach(function(n){io.observe(n);});
  }

  // Session Planner logic
  function setupPlanner(){
    var form = document.getElementById('planner-form');
    var buildBtn = document.getElementById('build-plan');
    var copyBtn = document.getElementById('copy-plan');
    var downloadBtn = document.getElementById('download-plan');
    var output = document.getElementById('plan-output');

    function gather(){
      var data = {};
      var fd = new FormData(form);
      data.name = (fd.get('name')||'').trim();
      data.focus = fd.get('focus') || 'clarity';
      data.duration = parseInt(fd.get('duration')||30,10);
      data.habits = fd.getAll('habits');
      return data;
    }

    function buildText(d){
      var lines = [];
      var greet = d.name?('Plan for '+d.name):'Personal plan';
      lines.push(greet);
      lines.push('Focus: '+(d.focus||'clarify priorities'));
      lines.push('Session length: '+d.duration+' minutes');
      lines.push('Includes: '+(d.habits.length?d.habits.join(', '):'none'));
      lines.push('\nSteps:');

      // Simple composition algorithm
      var core = Math.max(10, Math.min(60, d.duration));
      var anchor = Math.round(core * 0.2);
      var practice = Math.round(core * 0.5);
      var review = core - anchor - practice;

      lines.push('1) Anchor ('+anchor+' min) — a short cue to arrive: '+(d.habits.indexOf('breath')>-1? 'breath practice':'silent check-in'));
      lines.push('2) Practice ('+practice+' min) — focused work: choose 1 task aligned with your focus');
      lines.push('3) Review ('+review+' min) — quick notes and a single tweak for next time');

      lines.push('\nMicro-habits to keep:');
      if(d.habits.indexOf('breath')>-1) lines.push('- 1-minute breath cue at start');
      if(d.habits.indexOf('movement')>-1) lines.push('- brief standing stretch at midpoint');
      if(d.habits.indexOf('intake')>-1) lines.push('- water check after session');
      if(d.habits.indexOf('reflection')>-1) lines.push('- jot one sentence of what changed');

      lines.push('\nWeekly checkpoint: choose one short question to answer on Sunday: What move mattered most?');
      lines.push('\nNotes: This plan is a practical framework — small, repeatable changes to steady your days.');
      return lines.join('\n');
    }

    function setOutput(text){
      output.textContent = text;
      copyBtn.disabled = !text;
      downloadBtn.disabled = !text;
    }

    buildBtn.addEventListener('click', function(){
      var data = gather();
      var text = buildText(data);
      setOutput(text);
    });

    copyBtn.addEventListener('click', function(){
      var txt = output.textContent;
      if(!txt) return;
      if(navigator.clipboard && navigator.clipboard.writeText){
        navigator.clipboard.writeText(txt).then(function(){
          copyBtn.textContent = 'Copied';
          setTimeout(function(){copyBtn.textContent='Copy summary';},1600);
        });
      } else {
        var ta = document.createElement('textarea');
        ta.value = txt; document.body.appendChild(ta); ta.select();
        try{document.execCommand('copy'); copyBtn.textContent='Copied'; setTimeout(function(){copyBtn.textContent='Copy summary';},1600);}catch(e){}
        document.body.removeChild(ta);
      }
    });

    downloadBtn.addEventListener('click', function(){
      var txt = output.textContent;
      if(!txt) return;
      var blob = new Blob([txt],{type:'text/plain;charset=utf-8'});
      var url = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = url; a.download = 'session-plan.txt';
      document.body.appendChild(a); a.click(); setTimeout(function(){URL.revokeObjectURL(url);document.body.removeChild(a);},100);
    });
  }

  document.addEventListener('DOMContentLoaded', function(){
    setupReveal();
    setupPlanner();
  });
})();
"} 
